        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly supplies this proposed framing while leaving actual handoffs, required information and publication intentions to be established."
    }
  },
  "signal_basis": {
    "component_id": "C001.signal_basis",
    "value": "Link account and schedule events, check schedule lineage, record relevant handling events, and document offline preparation with reports and unknowns labeled. The assumed signal is an internally consistent sequence connecting the account, participants, preparation and schedule versions through publication.",
    "scope": "A bounded cohort's documented onboarding histories; proposed observations, with reported offline activity distinguished from logged events.",
